/**
 * Platform detection and shortcut formatting.
 *
 * Single source of truth for "Cmd on macOS, Ctrl elsewhere" so labels in
 * JSX/tooltips can never drift from the keydown handler. Detection prefers
 * `navigator.userAgentData.platform` (Chromium/WebView2), then `userAgent`,
 * then the deprecated `navigator.platform` as a last resort.
 */

export function isMacOS(): boolean { /* ... */ }

export const IS_MAC = isMacOS();

/** "⌘" on macOS, "Ctrl" on Windows/Linux — for prose, prefer formatShortcut(). */
export const MOD_KEY_LABEL = IS_MAC ? '⌘' : 'Ctrl';

/** "⌘O" on macOS, "Ctrl+O" elsewhere. */
export function formatShortcut(key: string): string { /* ... */ }

/**
 * True when the platform modifier is held. Accepts both Cmd and Ctrl on
 * either platform so shortcuts keep working even if detection is wrong
 * (e.g. exotic WebView UA) or the user remaps keys.
 */
export function isModKey(e: KeyboardEvent | { metaKey: boolean; ctrlKey: boolean }): boolean { /* ... */ }


/**
 * Custom project preferences — per-project “never pack” paths,
 * favorite flag, and a user-written note/comment.
 *
 * Persisted in localStorage under `ptt.projectPrefs`. Structure is kept
 * compatible with FolderHistoryEntry style parsing: defensive, tolerant of
 * missing fields, and de-duplicated by a stable path key.
 */

export interface ProjectPref {
  path: string;
  name: string;
  favorite: boolean;
  /** Free-form user comment describing why paths were deselected. */
  note: string;
  /** Relative (repo-root) paths deselected by the user that should be excluded. */
  deselectPaths: string[];
  lastUsedAt: number;
}

export const PROJECT_PREFS_KEY = 'ptt.projectPrefs';
export const MAX_PROJECT_PREFS = 60;

/** Stable key matching folderHistoryKey semantics. */
export function projectPrefKey(path: string): string { /* ... */ }

function folderName(path: string): string { /* ... */ }

function parseProjectPref(raw: unknown): ProjectPref | null { /* ... */ }

export function parseProjectPrefs(raw: string | null): ProjectPref[] { /* ... */ }

/** Favorites first, then most-recently used. */
export function sortProjectPrefs(a: ProjectPref, b: ProjectPref): number { /* ... */ }

export function readProjectPrefs(): ProjectPref[] { /* ... */ }

export function writeProjectPrefs(prefs: ProjectPref[]): void { /* ... */ }

export function rememberProject(
  prefs: ProjectPref[],
  path: string,
  now = Date.now(),
): ProjectPref[] { /* ... */ }

export function setProjectFavorite(
  prefs: ProjectPref[],
  path: string,
  favorite: boolean,
): ProjectPref[] { /* ... */ }

export function setProjectNote(
  prefs: ProjectPref[],
  path: string,
  note: string,
): ProjectPref[] { /* ... */ }

export function addDeselectPaths(
  prefs: ProjectPref[],
  path: string,
  paths: string[],
): ProjectPref[] { /* ... */ }

export function removeDeselectPaths(
  prefs: ProjectPref[],
  path: string,
  paths: string[],
): ProjectPref[] { /* ... */ }

function normalizeDeselectPath(p: string): string { /* ... */ }

function unionNormalized(a: string[], b: string[]): string[] { /* ... */ }

function differenceNormalized(a: string[], b: string[]): string[] { /* ... */ }

function updateDeselectPaths(
  prefs: ProjectPref[],
  path: string,
  paths: string[],
  combine: (current: string[], incoming: string[]) => string[],
): ProjectPref[] { /* ... */ }

export interface DeselectDelta {
  /** Files the user just unchecked — must be excluded on replay. */
  turnedOff: string[];
  /** Files the user just re-checked — must no longer be excluded. */
  turnedOn: string[];
}

/** Apply one user selection action to the saved replay list. */
export function applyDeselectDelta(
  prefs: ProjectPref[],
  path: string,
  delta: DeselectDelta,
): ProjectPref[] { /* ... */ }

export function clearDeselectPaths(prefs: ProjectPref[], path: string): ProjectPref[] { /* ... */ }

export function removeProject(prefs: ProjectPref[], path: string): ProjectPref[] { /* ... */ }


/**
 * Browser-mode port of `src/core/secrets.rs`. Keep the rule list in sync with the Rust file:
 * both implementations are checked against the same fixtures in `ui/e2e/secrets.spec.ts`
 * and `tests/phase1_regressions.rs`.
 *
 * Best-effort safety net: it masks recognizable credential shapes only.
 */

export interface RedactionSummary {
  totalRedactions: number;
  kinds: [string, number][];
  redactionEnabled?: boolean;
  filesScanned?: number;
  filesSkipped?: number;
}

interface SecretRule {
  kind: string;
  pattern: RegExp;
  replacement: string;
  /** When true, the captured value (group 2) is skipped if it is a documented placeholder. */
  placeholderAware?: boolean;
  /** When true, the captured value (group 2) must be >= 32 chars and have Shannon entropy > 4.5 bits/char. */
  highEntropy?: boolean;
}

export function shannonEntropy(s: string): number { /* ... */ }

// Global flag so `String.prototype.replace` replaces every occurrence.
const SECRET_RULES: readonly SecretRule[] = [
  {
    kind: 'PRIVATE_KEY',
    pattern:
      /-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----[\r\n]+[A-Za-z0-9+/=:, \t\r\n-]+?(?:-----END [A-Z0-9 ]*PRIVATE KEY-----|$)/g,
    replacement: '[REDACTED: PRIVATE_KEY]',
  },
  {
    kind: 'AWS_ACCESS_KEY',
    pattern: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/g,
    replacement: '[REDACTED: AWS_ACCESS_KEY]',
  },
  {
    kind: 'ANTHROPIC_API_KEY',
    pattern: /\bsk-ant-[A-Za-z0-9_-]{20,}\b/g,
    replacement: '[REDACTED: ANTHROPIC_API_KEY]',
  },
  {
    kind: 'OPENAI_API_KEY',
    pattern: /\bsk-[A-Za-z0-9_-]{20,}/g,
    replacement: '[REDACTED: OPENAI_API_KEY]',
  },
  {
    kind: 'GOOGLE_API_KEY',
    pattern: /\bAIza[0-9A-Za-z_-]{35}\b/g,
    replacement: '[REDACTED: GOOGLE_API_KEY]',
  },
  {
    kind: 'STRIPE_KEY',
    pattern: /\b(?:sk|rk)_(?:live|test)_[0-9A-Za-z]{20,}\b/g,
    replacement: '[REDACTED: STRIPE_KEY]',
  },
  {
    kind: 'GITHUB_TOKEN',
    pattern: /\bgh[pousr]_[A-Za-z0-9]{36,}\b/g,
    replacement: '[REDACTED: GITHUB_TOKEN]',
  },
  {
    kind: 'GITHUB_TOKEN',
    pattern: /\bgithub_pat_[A-Za-z0-9_]{22,}\b/g,
    replacement: '[REDACTED: GITHUB_TOKEN]',
  },
  {
    kind: 'SLACK_TOKEN',
    pattern: /\bxox[abposr]-[A-Za-z0-9-]{10,}/g,
    replacement: '[REDACTED: SLACK_TOKEN]',
  },
  {
    kind: 'GITLAB_TOKEN',
    pattern: /\bglpat-[0-9A-Za-z_-]{20,}\b/g,
    replacement: '[REDACTED: GITLAB_TOKEN]',
  },
  {
    kind: 'HUGGINGFACE_TOKEN',
    pattern: /\bhf_[A-Za-z0-9]{34,}\b/g,
    replacement: '[REDACTED: HUGGINGFACE_TOKEN]',
  },
  {
    kind: 'NPM_TOKEN',
    pattern: /\bnpm_[A-Za-z0-9]{36}\b/g,
    replacement: '[REDACTED: NPM_TOKEN]',
  },
  {
    // Three base64url segments, the first two starting with `eyJ` (JSON `{"`).
    kind: 'JWT_TOKEN',
    pattern: /\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g,
    replacement: '[REDACTED: JWT_TOKEN]',
  },
  {
    kind: 'URL_PASSWORD',
    pattern: /([a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/\s:@]+:)[^@\s"'`[][^@\s"'`]*(@)/g,
    replacement: '$1[REDACTED: URL_PASSWORD]$2',
  },
  {
    kind: 'PASSWORD',
    pattern: /((?:^|[\s;{,])(?:password|pwd)=)([^=;\s"'<>`)&}[][^;\s"'<>`)&}]*)/gi,
    replacement: '$1[REDACTED: PASSWORD]',
    placeholderAware: true,
  },
  {
    kind: 'PASSWORD',
    pattern: /^((?:export[ \t]+)?[A-Z][A-Z0-9_]*(?:PASSWORD|PWD)=)([^=;\s"'<>`)&}[][^\s"'<>`)&};]*)/gm,
    replacement: '$1[REDACTED: PASSWORD]',
    placeholderAware: true,
  },
  {
    kind: 'ENV_SECRET',
    pattern: /^((?:export[ \t]+)?[A-Z][A-Z0-9_]*_(?:SECRET|TOKEN|API_KEY|PRIVATE_KEY)=)([^\r\n#;]+)/gm,
    replacement: '$1[REDACTED: ENV_SECRET]',
    placeholderAware: true,
  },
  {
    kind: 'AZURE_KEY',
    pattern: /(AccountKey=)[A-Za-z0-9+/=]{40,}/gi,
    replacement: '$1[REDACTED: AZURE_KEY]',
  },
  {
    kind: 'SENDGRID_KEY',
    pattern: /\bSG\.[A-Za-z0-9_-]{22}\.[A-Za-z0-9_-]{43}\b/g,
    replacement: '[REDACTED: SENDGRID_KEY]',
  },
  {
    kind: 'DISCORD_TOKEN',
    pattern: /\b[MN][A-Za-z0-9]{23,25}\.[A-Za-z0-9_-]{6}\.[A-Za-z0-9_-]{27,38}\b/g,
    replacement: '[REDACTED: DISCORD_TOKEN]',
  },
  {
    kind: 'HIGH_ENTROPY_SECRET',
    pattern:
      /((?:^|[\s,;{(])(?:[a-zA-Z0-9_'"-]*?(?:key|auth|cred|bearer|cert)[a-zA-Z0-9_'"-]*)\s*[:=]\s*["']?)([^"'\s;,\r\n]{32,})(["']?)/gi,
    replacement: '[REDACTED: HIGH_ENTROPY_SECRET]',
    highEntropy: true,
  },
];

function isEnvPlaceholder(rawVal: string): boolean { /* ... */ }

