/* ─── Types ──────────────────────────────────────────── */

export interface FileNode {
  path: string;
  name: string;
  is_dir: boolean;
  size?: number;
  selected: boolean;
  git_status?: string;
}

export interface GitRepoContext {
  isGitRepo: boolean;
  currentBranch?: string | null;
  baseBranch?: string | null;
  fileStatuses: Record<string, string>;
  modifiedFiles: string[];
  branchChangedFiles: string[];
  recentCommits: string[];
}

export interface ScanResult {
  root: string;
  revision: number;
  nodes: FileNode[];
  junkDirs?: string[];
  gitContext?: GitRepoContext;
}

export interface PackOptions {
  format: string;
  include_summary: boolean;
  max_file_size?: number;
  redact_secrets?: boolean;
  full_preview?: boolean;
  skeleton_files?: string[];
  include_git_diff?: boolean;
  task_prompt?: string;
  tokenizer_model?: string;
}

export interface FileTokenStat {
  path: string;
  bytes: number;
  tokens: number;
  mode: 'full' | 'skeleton';
}

export interface PackTokenStats {
  files: number;
  tokens: number;
  contentTokens?: number;
  overheadTokens?: number;
  tokenizerExact?: boolean;
}

export interface GenerateOutputResponse {
  preview: string;
  truncatedPreview: boolean;
  totalBytes: number;
  totalChars: number;
  totalTokens: number;
  contentTokens?: number;
  overheadTokens?: number;
  tokenizerExact?: boolean;
  filesPacked: number;
  fileTokens?: FileTokenStat[];
  redactions: RedactionSummary;
}

export interface RelatedFiles {
  target: string;
  imports: string[];
  importers: string[];
  tests: string[];
}

export interface TreeNode {
  name: string;
  path: string;
  isDir: boolean;
  size?: number;
  selected: boolean;
  gitStatus?: string;
